-- Справка слова («карточка слова», PROJECT.md → «Макет «Карточка слова»»): у
-- урока-слова своя короткая шпаргалка для новичка (lessons.script.wordCard,
-- в обменном JSON — поле wordCard). Ученик открывает её тапом по слову в
-- выученной фразе. Правило для автора/модели, собирающей урок: как выглядит
-- хорошая справка. Таблиц и колонок не меняем — справка лежит в jsonb script,
-- как reviewCards. Идемпотентно: вставка только если такого правила ещё нет.
insert into public.lesson_rules (rule_text, sort_order, category)
select
  'Урок-слово (между Стартом и Финалом) отдаёт в JSON справку слова wordCard: { tag?, nodes: [...] } — короткую шпаргалку, по которой новичок за несколько секунд вспомнит, как слово работает. tag — метка над словом, 2–3 слова («служебное слово», «глагол · форма -ing»). nodes — блоки в любом порядке, лучше 2–3 понятных, чем пять: text { text } — одно-два предложения, слово в **звёздочках** выделяется; table { head, rows, mark } — когда у слова несколько форм (he: он / его / ему), 2–4 столбца, mark — номер строки (с 0), которая есть во фразе ученика; formula { parts, result } — когда слово собирается из частей (I’m + try + ing = I’m trying); cases { items: [{ label, example, tr, mark }] } — когда слово работает по-разному (to: перед действием / перед местом), 2–3 случая; dialog { left, right, lines: [{ side, text, tr, neg }] } — «Пример диалога». Пиши простыми русскими словами, как другу, без терминов: «после to идёт действие», а не «инфинитив». Диалог — мини-сюжет на 4–6 реплик (имена по умолчанию «Пит» слева, «Анна» справа — left и right можно не писать), под каждой репликой перевод в tr, слово из урока выделено **звёздочками**, и обязательно хотя бы одна реплика с отрицанием и neg: true (не/not подсветятся). side: l — слева, r — справа. Справка не повторяет урок и не задаёт вопросов — только напоминает.',
  220,
  'principle'
where not exists (
  select 1 from public.lesson_rules
  where rule_text like 'Урок-слово (между Стартом и Финалом) отдаёт в JSON справку слова wordCard%'
);
